DROP TABLE IF EXISTS `tb_master_barang_all_salah`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `tb_master_barang_all_salah` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `kd_barang` varchar(25) NOT NULL,
  `kode_barang_system` varchar(50) NOT NULL,
  `nama_barang` text NOT NULL,
  `kd_supplier` varchar(25) NOT NULL,
  `bhn_aktif` text NOT NULL,
  `satuan` text NOT NULL,
  `p` int(11) NOT NULL,
  `l` int(11) NOT NULL,
  `t` int(11) NOT NULL,
  `berat` int(11) NOT NULL,
  `kubikasi` text NOT NULL,
  `qty_min` int(11) NOT NULL,
  `id_gudang` int(11) DEFAULT NULL,
  `id_wilayah` int(11) DEFAULT NULL,
  `hpp` decimal(15,2) NOT NULL DEFAULT 0.00,
  PRIMARY KEY (`id`),
  KEY `fk_barang` (`kd_barang`),
  KEY `fk_nmbarang` (`nama_barang`(768)),
  KEY `fk_suplier` (`kd_supplier`),
  KEY `idx_gudang_wilayah` (`id_gudang`,`id_wilayah`),
  KEY `idx_barang_kd_barang` (`kd_barang`),
  KEY `idx_barang` (`kd_barang`)
) ENGINE=InnoDB AUTO_INCREMENT=6045 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

